// ---- Standard 12 fl oz can (copied unchanged from the house snippet) ----
const shape = 'M61 41Q100 32 139 41L145 58V220Q145 233 100 233T55 220V58Z';
function can(slug, title, label, color, extraDefs = '', { lid = 'silver', speckle = true, bar = .18 } = {}) {
  const gold = lid === 'gold';
  return wrap(slug, title, `${shadow(58)}
<path d="${shape}" fill="${color}"/>
<g clip-path="${ref('bodyclip')}">
${label}
<path d="${shape}" fill="${ref('shade')}" opacity=".85"/>
<path d="M65 62V213" fill="none" stroke="#fff" stroke-opacity="${bar}" stroke-width="3.1"/>
<path d="M138 62V213" fill="none" stroke="#fff" stroke-opacity=".09" stroke-width="1.3"/>
${speckle ? Array.from({ length: 19 }, (_, i) => `<ellipse cx="${65 + i * 29 % 69}" cy="${67 + i * 43 % 145}" rx="${i % 4 ? .6 : 1.05}" ry="${i % 4 ? 1 : 1.6}" fill="#fff" opacity=".15"/>`).join('') : ''}
</g>
<ellipse cx="100" cy="41" rx="39" ry="8" fill="${ref('metal')}" stroke="${gold ? '#a98a35' : '#9ca7a4'}" stroke-width="${gold ? 1.5 : 1.1}"/>
${gold ? '<ellipse cx="100" cy="41" rx="38.4" ry="7.5" fill="#d9b548" opacity=".36"/>' : ''}
<ellipse cx="100" cy="41" rx="34" ry="5.5" fill="none" stroke="${gold ? '#b3923c' : '#8d9892'}" stroke-width=".8"/>
<ellipse cx="105" cy="42" rx="8" ry="3.5" fill="${gold ? '#7a6a3c' : '#657169'}"/>
<path d="M93 39h10q6 0 5 4t-8 3h-6q-6-1-1-7" fill="none" stroke="${gold ? '#efe0a6' : '#e6e8de'}" stroke-width="2.4"/>
<path d="M58 226q42 12 84 0" fill="none" stroke="${ref('metal')}" stroke-width="4"/>
<path d="M61 230q39 7 78 0" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="1"/>
`, `<clipPath id="__ID__bodyclip"><path d="${shape}"/></clipPath>${extraDefs}`);
}

const TEAL = '#0b5a4f';
const r2 = v => Math.round(v * 100) / 100;
// rim ring dots sit on the same ellipse the traced ring text was re-curved onto
const rimY = x => r2(44.6 + 9.4 * Math.sqrt(1 - ((x - 100) / 46) ** 2));

// ---- Flavor art, redrawn as clean vector shapes ----
// Positions are measured on the packshot's flavor panel in a 400 x 392 grid (x across the
// front of the can, y down from the teal band) and mapped onto the house can here.
const X = cx => r2(55 + cx * .225);
const Y = cy => r2(122.6 + cy * .2648);
const pt = (cx, cy) => `${X(cx)} ${Y(cy)}`;
// closed smooth curve (Catmull-Rom as cubics) through grid points
function blob(pts) {
  const p = pts.map(([a, b]) => [X(a), Y(b)]);
  const n = p.length;
  let d = `M${p[0][0]} ${p[0][1]}`;
  for (let i = 0; i < n; i++) {
    const p0 = p[(i - 1 + n) % n], p1 = p[i], p2 = p[(i + 1) % n], p3 = p[(i + 2) % n];
    d += `C${r2(p1[0] + (p2[0] - p0[0]) / 6)} ${r2(p1[1] + (p2[1] - p0[1]) / 6)} ${r2(p2[0] - (p3[0] - p1[0]) / 6)} ${r2(p2[1] - (p3[1] - p1[1]) / 6)} ${p2[0]} ${p2[1]}`;
  }
  return d + 'Z';
}
// open smooth curve through grid points
function curve(pts) {
  const p = pts.map(([a, b]) => [X(a), Y(b)]);
  let d = `M${p[0][0]} ${p[0][1]}`;
  for (let i = 0; i < p.length - 1; i++) {
    const p0 = p[Math.max(i - 1, 0)], p1 = p[i], p2 = p[i + 1], p3 = p[Math.min(i + 2, p.length - 1)];
    d += `C${r2(p1[0] + (p2[0] - p0[0]) / 6)} ${r2(p1[1] + (p2[1] - p0[1]) / 6)} ${r2(p2[0] - (p3[0] - p1[0]) / 6)} ${r2(p2[1] - (p3[1] - p1[1]) / 6)} ${p2[0]} ${p2[1]}`;
  }
  return d;
}
// crimped bottle cap seen at an angle: skirt (edge colors) under a flat face
function scallop(x, y, rx, ry) {
  let d = '';
  for (let i = 0; i < 42; i++) {
    const a = i / 42 * Math.PI * 2, k = i % 2 ? 1 : 1.09;
    d += `${i ? 'L' : 'M'}${r2(x + Math.cos(a) * rx * k)} ${r2(y + Math.sin(a) * ry * k)}`;
  }
  return d + 'Z';
}
function cap(cx, cy, rx, ry, rot, face, edge, dark, depth = 2.6) {
  const x = X(cx), y = Y(cy);
  return `<g transform="rotate(${rot} ${x} ${y})"><path d="${scallop(x, y + depth, rx, ry)}" fill="${dark}"/><path d="${scallop(x, y + depth * .45, rx, ry)}" fill="${edge}"/><ellipse cx="${x}" cy="${r2(y - .3)}" rx="${r2(rx * .88)}" ry="${r2(ry * .86)}" fill="${face}"/><ellipse cx="${r2(x - rx * .25)}" cy="${r2(y - ry * .3)}" rx="${r2(rx * .4)}" ry="${r2(ry * .3)}" fill="#fff" opacity=".45"/></g>`;
}
// leaf between two grid points, bulging w units each side, with a midrib
function leaf(a, b, w, fill, vein, bend = 0) {
  const [x1, y1, x2, y2] = [X(a[0]), Y(a[1]), X(b[0]), Y(b[1])];
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy), nx = -dy / L, ny = dx / L;
  const mx = (x1 + x2) / 2 + nx * bend, my = (y1 + y2) / 2 + ny * bend;
  const c1 = `${r2(mx + nx * w)} ${r2(my + ny * w)}`, c2 = `${r2(mx - nx * w)} ${r2(my - ny * w)}`;
  return `<path d="M${r2(x1)} ${r2(y1)}Q${c1} ${r2(x2)} ${r2(y2)}Q${c2} ${r2(x1)} ${r2(y1)}Z" fill="${fill}"/><path d="M${r2(x1)} ${r2(y1)}Q${r2(mx)} ${r2(my)} ${r2(x2)} ${r2(y2)}" fill="none" stroke="${vein}" stroke-width=".7" stroke-linecap="round"/>`;
}
function star(cx, cy, R, r, n, fill, rot = 0) {
  let d = '';
  for (let i = 0; i < n * 2; i++) {
    const a = (i / (n * 2) + rot) * Math.PI * 2, k = i % 2 ? r : R;
    d += `${i ? 'L' : 'M'}${r2(X(cx) + Math.cos(a) * k)} ${r2(Y(cy) + Math.sin(a) * k)}`;
  }
  return `<path d="${d}Z" fill="${fill}"/>`;
}
const bubbles = (list, c = '#fff') => list.map(([cx, cy, r]) => `<circle cx="${X(cx)}" cy="${Y(cy)}" r="${r}" fill="${c}" fill-opacity=".18" stroke="${c}" stroke-opacity=".55" stroke-width=".35"/>`).join('');
const sparkle = (cx, cy, s, c = '#fff') => `<path d="M${X(cx)} ${r2(Y(cy) - s)}L${r2(X(cx) + s * .18)} ${r2(Y(cy) - s * .18)}L${r2(X(cx) + s)} ${Y(cy)}L${r2(X(cx) + s * .18)} ${r2(Y(cy) + s * .18)}L${X(cx)} ${r2(Y(cy) + s)}L${r2(X(cx) - s * .18)} ${r2(Y(cy) + s * .18)}L${r2(X(cx) - s)} ${Y(cy)}L${r2(X(cx) - s * .18)} ${r2(Y(cy) - s * .18)}Z" fill="${c}"/>`;
const lg = (id, x1, y1, x2, y2, stops) => `<linearGradient id="__ID__${id}" gradientUnits="userSpaceOnUse" x1="${X(x1)}" y1="${Y(y1)}" x2="${X(x2)}" y2="${Y(y2)}">${stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join('')}</linearGradient>`;
const rg = (id, stops) => `<radialGradient id="__ID__${id}" cx=".38" cy=".32" r=".75">${stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join('')}</radialGradient>`;

// three-tone round object: radial gradient (highlight, base, shadow) plus a soft highlight
const rgc = (id, stops, cx = .36, cy = .3, r = .78) => `<radialGradient id="__ID__${id}" cx="${cx}" cy="${cy}" r="${r}">${stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join('')}</radialGradient>`;
// leaf with midrib and side veins
function vleaf(a, b, w, fill, shade, vein, bend = 0, n = 4) {
  const [x1, y1, x2, y2] = [X(a[0]), Y(a[1]), X(b[0]), Y(b[1])];
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy), nx = -dy / L, ny = dx / L;
  const mx = (x1 + x2) / 2 + nx * bend, my = (y1 + y2) / 2 + ny * bend;
  const P = (x, y) => `${r2(x)} ${r2(y)}`;
  let v = '';
  for (let i = 1; i <= n; i++) {
    const t = i / (n + 1), qx = (1 - t) ** 2 * x1 + 2 * t * (1 - t) * mx + t * t * x2, qy = (1 - t) ** 2 * y1 + 2 * t * (1 - t) * my + t * t * y2;
    const s = w * .42 * Math.sin(Math.PI * t);
    v += `M${P(qx, qy)}l${r2(nx * s + dx / L * s * .6)} ${r2(ny * s + dy / L * s * .6)}M${P(qx, qy)}l${r2(-nx * s + dx / L * s * .6)} ${r2(-ny * s + dy / L * s * .6)}`;
  }
  return `<path d="M${P(x1, y1)}Q${P(mx + nx * w, my + ny * w)} ${P(x2, y2)}Q${P(mx - nx * w, my - ny * w)} ${P(x1, y1)}Z" fill="${fill}"/>`
    + `<path d="M${P(x1, y1)}Q${P(mx - nx * w, my - ny * w)} ${P(x2, y2)}Q${P(mx - nx * w * .2, my - ny * w * .2)} ${P(x1, y1)}Z" fill="${shade}"/>`
    + `<path d="M${P(x1, y1)}Q${P(mx, my)} ${P(x2, y2)}${v}" fill="none" stroke="${vein}" stroke-width=".5" stroke-opacity=".8" stroke-linecap="round"/>`;
}
// bubbles along a trail: deterministic offsets
function trail(x0, y0, x1, y1, n, c = '#fff', k = 1) {
  let s = '';
  for (let i = 0; i < n; i++) {
    const t = n > 1 ? i / (n - 1) : 0, wob = Math.sin(i * 2.3 + k) * 6;
    const x = r2(X(x0 + (x1 - x0) * t + wob * 3)), y = r2(Y(y0 + (y1 - y0) * t + Math.cos(i * 1.7 + k) * 10));
    const r = r2(.45 + ((i * 7 + k * 3) % 5) * .22);
    s += `<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" fill-opacity=".16" stroke="${c}" stroke-opacity=".6" stroke-width=".3"/><circle cx="${r2(x - r * .35)}" cy="${r2(y - r * .35)}" r="${r2(r * .28)}" fill="${c}" opacity=".8"/>`;
  }
  return s;
}
function bigcap(cx, cy, rx, ry, rot, id, edge, dark, depth) {
  const x = X(cx), y = Y(cy);
  return `<g transform="rotate(${rot} ${x} ${y})"><path d="${scallop(x, y + depth, rx, ry)}" fill="${dark}"/><path d="${scallop(x, y + depth * .45, rx, ry)}" fill="${edge}"/><ellipse cx="${x}" cy="${r2(y - .3)}" rx="${r2(rx * .88)}" ry="${r2(ry * .86)}" fill="${ref(id)}"/><ellipse cx="${x}" cy="${r2(y - .3)}" rx="${r2(rx * .7)}" ry="${r2(ry * .68)}" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width=".6"/><ellipse cx="${r2(x - rx * .3)}" cy="${r2(y - ry * .35)}" rx="${r2(rx * .3)}" ry="${r2(ry * .2)}" fill="#fff" opacity=".55"/></g>`;
}
const poly = pts => 'M' + pts.map(([a, b]) => `${X(a)} ${Y(b)}`).join('L') + 'Z';

