function zevia(slug, title, accent) {
  const f = F[slug];
  const { defs, art } = ART[slug]();
  const label = `<rect x="50" y="${r2(f.te - 2)}" width="100" height="${r2(240 - f.te)}" fill="${ref('bg')}"/>
${art}
<rect x="50" y="30" width="100" height="${r2(f.te - 30)}" fill="${TEAL}"/>
<path d="${RIM}" fill="#e6e6e4" fill-rule="evenodd"/>
${[68, 101.7, 134].map(x => `<ellipse cx="${x}" cy="${rimY(x)}" rx="1" ry=".95" fill="${accent}"/>`).join('')}
<path d="${WORDMARK}" fill="#ebeae9" fill-rule="evenodd"/>
<path d="${LEAF}" fill="${accent}"/>
<path d="${SMB}" fill="#e9e9e7" fill-rule="evenodd"/>
<path d="${f.name}" fill="${f.ncol}" fill-rule="evenodd"/>
${text(74, r2(f.nfy + .75), 'NATURALLY FLAVORED', 2.4, f.ncol, 'font-weight="bold" textLength="22.5" lengthAdjust="spacingAndGlyphs"')}
${text(71.5, 213, '12 FL. OZ. (355 mL)', 2.4, '#ffffff', 'opacity=".85" textLength="19" lengthAdjust="spacingAndGlyphs"')}`;
  return can(slug, title, label, TEAL, defs);
}

